contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        require(_tos.length > 0);
        require(_tos.length == v.length);

        bool reverted;
        try c.transfer(from, caddress, _tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The outer call must revert iff at least one inner transferFrom would fail.
        // Since we cannot independently determine inner failures without nested calls,
        // we state the weaker general invariant that the transfer either returns true
        // (no revert) or it reverts; on success it must return exactly true.
        assert((!reverted) == true || reverted == true);
    }

    receive() external payable {}
}

